const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let teamData,allocationData,catalog;
function render(){const teams=teamData.records,rows=allocationData.records,ids=catalog.challenges.map(c=>c.id??c.challenge_id),name=id=>catalog.challenges.find(c=>(c.id??c.challenge_id)===id)?.name??id;
const cards=[['Fictional teams',teams.length,'Generated scenario · no actual team count'],['Fictional members',teams.reduce((n,t)=>n+t.team_size,0),'Four per fictional team'],['Scenario challenge rows',rows.length,'Multiple rows can belong to one fictional team'],['Observed responses',0,'No teams were contacted for this simulation']];
$('simulation-metrics').innerHTML=cards.map(([label,value,detail])=>`<div class="metric"><span class="metric-label">${esc(label)}</span><strong class="metric-value">${value}</strong><span class="metric-detail">${esc(detail)}</span></div>`).join('');
$('simulation-chart').innerHTML=ids.map(id=>{const selected=rows.filter(r=>r.challenge_id===id&&r.status!=='stopped'),n=new Set(selected.map(r=>r.team_id)).size;return`<div class="chart-row"><span class="chart-label" title="${esc(name(id))}">${esc(name(id))}</span><div class="chart-track"><div class="chart-bar simulation-bar" style="width:${100*n/teams.length}%"></div></div><span class="chart-value">${n} / ${teams.length}</span></div>`;}).join('');
$('simulation-ratings').innerHTML='<div class="friction-header"><span>Fictional scenario</span><span>Difficulty /5</span><span>Prizes /5</span></div>'+ids.map(id=>{const selected=rows.filter(r=>r.challenge_id===id),stats=key=>{const values=selected.map(r=>r[key]).filter(v=>Number.isFinite(v));return{mean:values.length?(values.reduce((n,v)=>n+v,0)/values.length).toFixed(1):'—',n:values.length};},difficulty=stats('simulated_difficulty_1_5'),prizes=stats('simulated_prize_importance_1_5');return`<div class="friction-row"><span title="${esc(name(id))}">${esc(name(id))}</span><span class="rating"><strong>${difficulty.mean}</strong><small class="sample-n">n=${difficulty.n} synthetic</small></span><span class="rating"><strong>${prizes.mean}</strong><small class="sample-n">n=${prizes.n} synthetic</small></span></div>`;}).join('');
const id=$('simulation-challenge').value,filtered=id==='all'?rows:rows.filter(r=>r.challenge_id===id);$('simulation-row-count').textContent=`${filtered.length} synthetic records · no real observations`;$('simulation-body').innerHTML=filtered.map(r=>`<tr><td>${esc(r.team_id)}</td><td>${esc(name(r.challenge_id))}</td><td>${esc(r.status)}</td><td>${r.person_count_allocated}</td><td>${r.effort_hours}</td><td>${r.simulated_difficulty_1_5??'—'} / 5</td><td>${r.simulated_prize_importance_1_5??'—'} / 5</td><td><span class="category-tag">SIMULATED</span></td></tr>`).join('');}
async function init(){[teamData,allocationData,catalog]=await Promise.all(['simulated-teams.json','simulated-team-challenges.json','catalog.json'].map(async name=>{const r=await fetch('./data/'+name);if(!r.ok)throw new Error('Scenario data unavailable');return r.json();}));for(const record of [...teamData.records,...allocationData.records]){if(record.source_type!=='synthetic'||record.is_observed!==false||record.scenario_only!==true)throw new Error('Scenario records must be explicitly marked synthetic.');}$('simulation-challenge').innerHTML='<option value="all">All challenges</option>'+catalog.challenges.map(c=>`<option value="${esc(c.id??c.challenge_id)}">${esc(c.name)}</option>`).join('');render();}
$('simulation-challenge').addEventListener('change',render);$('export-simulation').addEventListener('click',()=>{if(!teamData||!allocationData)return;const data={schema_version:1,source_type:'synthetic',is_observed:false,scenario_only:true,notice:'SIMULATED. Nine fictional teams; no teams contacted. Illustrative assumptions, not Discord findings.',teams:teamData,team_challenges:allocationData},url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='challenge-pulse-SIMULATED-scenario.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);});
init().catch(error=>{$('simulation-metrics').innerHTML=`<p class="notice">${esc(error.message)}. No fictional metrics are shown.</p>`;$('export-simulation').disabled=true;});
